import pandas as pd

def clean(df):
    df = df.copy()
    # strip whitespace from text columns safely
    for col in ["Category", "Region", "Product", "Date"]:
        if col in df.columns:
            df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # standardise known label variants
    region_map = {"Suoth": "South", "Nort": "North"}
    df["Region"] = df["Region"].replace(region_map)
    # ensure numeric types
    for col in ["Quantity", "Price", "Revenue"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    # fix cross-column rule: Revenue = Quantity * Price
    if {"Quantity", "Price"}.issubset(df.columns):
        df["Revenue"] = df["Quantity"] * df["Price"]
    # optional date normalisation – keep as string but try parse
    if "Date" in df.columns:
        # keep original string; parsing is attempted for validation only
        _ = pd.to_datetime(df["Date"], errors="coerce", format="%Y-%m-%d")
    return df

def answer(df):
    dfc = clean(df)
    # filter to Electronics category after cleaning
    sub = dfc[dfc["Category"] == "Electronics"]
    # drop rows with missing grouping key
    sub = sub.dropna(subset=["Region"])
    # total revenue by region
    grouped = sub.groupby("Region", dropna=True)["Revenue"].sum()
    # return plain dict with native numbers
    return {str(k): float(v) for k, v in grouped.items()}
